#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker is a raw C++ pointer (UArenaScoreTracker*) that is not a UPROPERTY, so it does not create a GC reference. The garbage collector collected the UArenaScoreTracker created in BeginPlay during play (log: 'LogGarbage: Collecting garbage: 412 objects purged' at 21:05:13, 14 s before the crash). On the next goal (21:05:27) OnGoalScored called ScoreTracker->AddPoints() on the dangling, already-collected pointer, causing EXCEPTION_ACCESS_VIOLATION reading 0xffffffffffffffff in UArenaScoreTracker::AddPoints (ArenaScoreTracker.cpp:18). Fixed by declaring ScoreTracker as UPROPERTY() TObjectPtr<UArenaScoreTracker> so the GC keeps it alive for the lifetime of the GameMode.",
  "no_colors_cause": "The packaged build never cooked the palette asset /Game/Data/Palettes/DA_Primary. Config/DefaultGame.ini has bCookAll=False and DirectoriesToAlwaysCook listed only /Game/Effects, and the palette is loaded at runtime via LoadObject (log: 'requested by async loading code'), which the cooker does not trace, so the asset was absent from the pak. In shipping, LoadObject failed ('LogStreaming: Error: Couldn't find file for package /Game/Data/Palettes/DA_Primary'), Palette stayed null and the game fell back to gray ('LogArena: Warning: Palette is null, using fallback gray'), so the arena rendered without colors. The editor run works because it loads assets from the source tree. Fixed by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to [/Script/UnrealEd.ProjectPackagingSettings]."
}
